        private async Task ReloadAsync()
        {
            await _reloadLock.WaitAsync().ConfigureAwait(false);
            try
            {
                await Task.Delay(100).ConfigureAwait(false);
                var config = await _loader.LoadAsync(_filePath).ConfigureAwait(false);
                Swap(config);
