            _watcher.Changed += async (s, e) =>
            { if (e.FullPath == _filePath) await ReloadAsync().ConfigureAwait(false); };
            _watcher.Created += async (s, e) =>
            { if (e.FullPath == _filePath) await ReloadAsync().ConfigureAwait(false); };
            _watcher.Renamed += async (s, e) =>
            { if (e.FullPath == _filePath) await ReloadAsync().ConfigureAwait(false); };
        }

